window.VN_LEARNING=window.VN_LEARNING||{};
window.VN_LEARNING["lesson-7"]={
  version:2,title:"Minerals",chapter:7,duration:"105–125 minutes",
  outcomes:["Explain how mineral bioavailability differs from the amount printed in a food table.","Build an iron strategy around nonheme sources, enhancers, inhibitors and assessment.","Connect phytate, food preparation and total intake to zinc adequacy.","Choose calcium sources by both content and absorption while keeping bone health multifactorial.","Plan iodine safely without treating kelp as a predictable supplement.","Explain why selenium exposure changes with soil and why a Brazil-nut dosing rule is unreliable.","Interpret diet, symptoms, biomarkers and supplements as complementary evidence rather than interchangeable proof."],
  modules:[
    {id:"iron",title:"Make nonheme iron work",summary:"Separate chemical identity from absorption pathway, then use meal design and risk assessment.",moments:[
      {id:"l7-m1",title:"Plant and animal foods contain the same element, but not the same iron form",highYield:"Nonheme iron is more sensitive to meal context than heme iron; the mineral itself is still iron.",teaching:["Iron is essential for hemoglobin, myoglobin, electron transport and many enzymes. Plant foods provide nonheme iron. Flesh foods provide nonheme iron plus heme iron. These are not two different elements; they enter different absorption pathways and respond differently to meal factors.","Legumes, tofu, tempeh, seeds, nuts, whole or enriched grains, fortified cereals and some vegetables contribute iron. Menstrual loss, pregnancy, growth, blood donation and endurance training can raise risk. Population targets account for bioavailability, but an old multiplier should not become an automatic supplement dose."],keyPoints:["Iron is present in hemoglobin and myoglobin.","Plant foods provide nonheme iron.","Heme and nonheme absorption differ.","Needs and losses vary by person."],visual:{title:"Iron from plate to tissue",kind:"flow",items:[{label:"Source",detail:"Legume, tofu, grain, seed, fortified food"},{label:"Meal context",detail:"Vitamin C enhances; phytate/polyphenols can inhibit"},{label:"Absorb",detail:"Enterocyte regulates uptake"},{label:"Transport",detail:"Transferrin carries iron"},{label:"Use/store",detail:"Hemoglobin, enzymes and ferritin"}]},mnemonic:{title:"S-M-A-T",cue:"Source · Meal · Absorb · Transport",explanation:"Do not jump from food iron to blood status without the middle steps."},goodToKnow:"The body regulates nonheme iron absorption partly in response to stores and need; lower stores can increase fractional absorption.",practiceConnection:"Assess symptoms and risk but use laboratory evaluation to diagnose iron deficiency. Fatigue alone is not specific.",activity:{prompt:"How does plant iron differ from heme iron?",options:[{text:"It is mainly nonheme iron and is more affected by meal factors",correct:true,feedback:"Correct. It is the same mineral in a different dietary form and absorption context."},{text:"It is a different chemical element",correct:false,feedback:"Both are iron; the forms and pathways differ."},{text:"It cannot be absorbed by humans",correct:false,feedback:"Nonheme iron is absorbed, though bioavailability varies."}]}} ,
      {id:"l7-m2",title:"Vitamin C can turn an iron-rich meal into a stronger plan",highYield:"Pair nonheme iron with vitamin-C-rich food and separate strong tea or coffee when iron status is a concern.",teaching:["Vitamin C enhances nonheme iron absorption by maintaining a soluble form and helping counter some inhibitory effects. Peppers, citrus, kiwi, strawberries, tomatoes and broccoli can be practical partners for beans, lentils, tofu, seeds and iron-fortified grains.","Phytate in grains and legumes and polyphenols in tea or coffee can reduce absorption in the same meal. This does not make those foods unhealthy. Soaking, sprouting, fermenting, leavening and varied preparation can reduce phytate, while timing tea or coffee away from an iron-focused meal can help when risk is elevated."],keyPoints:["Vitamin C enhances nonheme iron absorption.","Tea and coffee polyphenols can inhibit absorption.","Phytate is also found in iron-rich foods.","Preparation and timing can improve the pattern."],visual:{title:"Iron meal balance",kind:"comparison",items:[{label:"Anchor",detail:"Lentils, tofu, beans, seeds or fortified grain"},{label:"Enhance",detail:"Pepper, citrus, tomato, berries or broccoli"},{label:"Modify",detail:"Soak, sprout, ferment or leaven"},{label:"Separate if needed",detail:"Strong tea or coffee from the iron-focused meal"}]},mnemonic:{title:"Iron + C",cue:"Core source + Colour",explanation:"Pair the iron anchor with a colourful vitamin-C-rich food."},goodToKnow:"Dairy is not a meaningful iron source; a large calcium dose can affect iron absorption acutely, but overall dietary patterns matter more than banning calcium foods.",practiceConnection:"For low ferritin or pregnancy, coordinate individualized treatment rather than relying only on meal pairing.",activity:{prompt:"Which meal change most directly supports nonheme iron absorption?",options:[{text:"Add bell pepper to a lentil meal",correct:true,feedback:"Correct. Bell pepper supplies vitamin C."},{text:"Drink strong black tea with the meal",correct:false,feedback:"Tea polyphenols can inhibit nonheme iron absorption."},{text:"Remove every phytate-containing food",correct:false,feedback:"That would remove many nutritious iron sources; preparation and pairing are better tools."}]}}
    ]},
    {id:"zinc",title:"Work with phytate, not against the whole diet",summary:"Use food preparation, variety and assessment to support zinc without pathologizing legumes and grains.",moments:[
      {id:"l7-m3",title:"Zinc supports growth, repair, immunity and taste",highYield:"Vegetarian zinc planning focuses on total intake and bioavailability, especially when high-phytate staples dominate.",teaching:["Zinc is required by hundreds of enzymes and transcription factors. It supports growth, wound healing, immune function, DNA synthesis, reproduction and taste. Vegetarian sources include legumes, soy foods, nuts, seeds, whole grains and fortified cereals.","Phytate can bind zinc and reduce absorption. That does not make high-phytate foods harmful: the same foods provide protein, fibre, iron and other nutrients. A varied pattern with adequate energy and several zinc sources is more useful than a single food score. Laboratory zinc markers are imperfect, so assessment combines diet, symptoms, growth and medical context."],keyPoints:["Zinc supports enzymes, growth and repair.","Legumes, seeds and grains provide zinc.","Phytate can lower absorption.","Status assessment is contextual."],visual:{title:"Zinc risk equation",kind:"map",items:[{label:"Need",detail:"Growth, pregnancy, healing and illness can change demand"},{label:"Intake",detail:"Number, portion and frequency of zinc sources"},{label:"Bioavailability",detail:"Phytate and food preparation"},{label:"Adaptation",detail:"The body may adjust absorption and losses"},{label:"Context",detail:"Symptoms, growth and health conditions"}]},mnemonic:{title:"ZINC",cue:"Zest/taste · Immunity · New tissue · Catalysis",explanation:"A memory cue for major zinc functions."},goodToKnow:"Serum zinc is affected by inflammation, fasting and time of day; one result requires clinical interpretation.",practiceConnection:"Do not use high-dose zinc casually. Chronic excess can impair copper status and cause other adverse effects.",activity:{prompt:"Which vegetarian food group commonly contributes zinc?",options:[{text:"Legumes, nuts and seeds",correct:true,feedback:"Correct. They provide zinc along with protein and other minerals."},{text:"Refined sugar",correct:false,feedback:"Sugar is not a meaningful zinc source."},{text:"Fruit juice only",correct:false,feedback:"Most juices are not substantial zinc sources."}]}} ,
      {id:"l7-m4",title:"Soaking, sprouting and fermentation can improve access",highYield:"Processing can reduce phytate; soaking does not increase phytate as an old quiz item suggests.",teaching:["Soaking and discarding soak water can remove some soluble compounds; sprouting activates phytase; fermentation and yeast leavening can further break down phytate. The magnitude varies by food and method, but the direction is generally toward improved mineral bioavailability rather than more zinc-blocking phytate.","Canned beans and fermented soy foods are convenient options, while nuts and seeds add concentrated zinc and energy. The goal is not to process every food the same way. Rotate food forms, include adequate portions and reserve supplementation for assessed needs."],keyPoints:["Soaking generally reduces rather than raises phytate.","Sprouting activates phytase.","Fermentation and leavening can improve availability.","Variety of food forms supports adequacy."],visual:{title:"Phytate-lowering toolbox",kind:"sequence",items:[{label:"Soak",detail:"Hydrate and remove some soluble compounds"},{label:"Sprout",detail:"Activate seed enzymes"},{label:"Ferment",detail:"Microbial and enzymatic breakdown"},{label:"Leaven",detail:"Time and acidity support phytate reduction"},{label:"Combine",detail:"Use several zinc-rich foods across the day"}]},mnemonic:{title:"SSFL",cue:"Soak · Sprout · Ferment · Leaven",explanation:"Four preparation methods that can improve mineral access."},goodToKnow:"Phytate also has biologic properties under study; nutrition planning does not require eliminating it.",practiceConnection:"Choose methods that fit culture, time and budget. A theoretically optimal method that is never used is not practical care.",activity:{prompt:"What usually happens to phytate during sprouting or fermentation?",options:[{text:"It is partly broken down, which can improve mineral availability",correct:true,feedback:"Correct. Enzymes and microbes can degrade phytate."},{text:"It always doubles",correct:false,feedback:"That reverses the typical effect."},{text:"It changes zinc into iron",correct:false,feedback:"Minerals do not transform into one another during food preparation."}]}}
    ]},
    {id:"calcium-bone",title:"Think beyond calcium totals",summary:"Combine absorbed calcium, vitamin D, protein, activity and life-stage factors for bone health.",moments:[
      {id:"l7-m5",title:"Calcium content and calcium absorption are not the same",highYield:"Low-oxalate greens, calcium-set tofu and fortified beverages can be useful; spinach calcium is poorly absorbed.",teaching:["Calcium supports bone and teeth, neuromuscular signalling, blood clotting and cell regulation. Vegetarian sources include dairy for those who use it, fortified plant beverages, calcium-set tofu, selected legumes, tahini and low-oxalate greens such as kale, bok choy and broccoli.","Oxalate strongly reduces calcium absorption from spinach and some other greens. A food can contain calcium on paper yet contribute little absorbed calcium. Fortified beverage absorption can be comparable to milk when the calcium is well suspended, but the carton should be shaken and the label checked because products vary."],keyPoints:["Calcium has structural and signalling roles.","Oxalate lowers absorption from spinach.","Low-oxalate greens can be well absorbed.","Fortified beverage labels and mixing matter."],visual:{title:"Calcium source quality",kind:"comparison",items:[{label:"Fortified beverage",detail:"Often useful if calcium and vitamin D are added; shake well"},{label:"Calcium-set tofu",detail:"Check ingredient and label; setting salt matters"},{label:"Low-oxalate greens",detail:"Kale, bok choy and broccoli offer absorbable calcium"},{label:"Spinach",detail:"Contains calcium but high oxalate limits absorption"}]},mnemonic:{title:"F-T-G",cue:"Fortified drink · Tofu · Greens",explanation:"Three practical vegan calcium anchors; verify labels and serving sizes."},goodToKnow:"Food tables and old equivalence claims can mislead when portion size, brand and absorption are not specified.",practiceConnection:"Map daily calcium anchors rather than relying on a rarely eaten 'calcium-rich' garnish.",activity:{prompt:"Which green has relatively poor calcium absorption because of oxalate?",options:[{text:"Spinach",correct:true,feedback:"Correct. Its calcium is poorly bioavailable."},{text:"Kale",correct:false,feedback:"Kale is a low-oxalate green with better calcium absorption."},{text:"Bok choy",correct:false,feedback:"Bok choy is also a useful low-oxalate source."}]}} ,
      {id:"l7-m6",title:"Bone health is a system",highYield:"Calcium matters, but bone also responds to vitamin D, protein, resistance and impact activity, hormones, smoking, alcohol, medicines and age.",teaching:["Bone is living tissue undergoing formation and resorption. Adequate calcium and vitamin D are necessary, while protein supplies matrix building blocks. Weight-bearing and resistance exercise stimulate bone and muscle. Energy deficiency, low body weight, menstrual disruption, smoking, high alcohol intake, glucocorticoids and several conditions can increase risk.","Spreading calcium-containing foods across the day can improve practical coverage, and absorption is efficient at moderate doses. But a quiz statement that osteoporosis damage 'cannot be repaired' is too absolute. Treatment can reduce fracture risk and sometimes improve bone density, though restoring lost architecture is not simple. Prevention and early assessment remain important."],keyPoints:["Bone remodels throughout life.","Calcium is necessary but not sufficient.","Exercise and protein support bone and muscle.","Treatment can improve outcomes; absolutes are misleading."],visual:{title:"Bone-strength framework",kind:"map",items:[{label:"Materials",detail:"Calcium, phosphate, protein and micronutrients"},{label:"Activation",detail:"Vitamin D and hormonal regulation"},{label:"Loading",detail:"Resistance and weight-bearing movement"},{label:"Protection",detail:"Avoid smoking, excess alcohol and chronic energy deficit"},{label:"Assessment",detail:"Life stage, medicines, falls and bone density when indicated"}]},mnemonic:{title:"BUILD",cue:"Building blocks · Use/load · Intake D · Lifestyle · Diagnosis",explanation:"A reminder that bone health is larger than one nutrient."},goodToKnow:"Large single calcium doses are absorbed less efficiently than moderate amounts; exact supplement timing depends on form, medicines and clinical plan.",practiceConnection:"Ask about falls, fractures, menstrual status, medicines and activity as well as calcium intake.",activity:{prompt:"Which statement best describes bone health?",options:[{text:"It reflects nutrients, hormones, activity, lifestyle, medicines and age",correct:true,feedback:"Correct. Calcium is one part of a wider system."},{text:"Calcium intake is the only determinant",correct:false,feedback:"Bone health is multifactorial."},{text:"Bone never changes after adolescence",correct:false,feedback:"Bone remodels throughout life."}]}}
    ]},
    {id:"iodine-others",title:"Use predictable iodine and mineral sources",summary:"Avoid both deficiency and excess, then place selenium and other minerals in a food-pattern context.",moments:[
      {id:"l7-m7",title:"Iodine needs a measured source",highYield:"Iodized salt or a measured supplement is more predictable than kelp; seaweed iodine can vary from too little to excessive.",teaching:["Iodine is required for thyroid hormone synthesis. People avoiding dairy, seafood and eggs can have lower intake, especially where plant foods reflect iodine-poor soil. Many specialty salts, sea salt and processed foods are not iodized, so 'uses salt' is not enough information.","Iodized salt provides a predictable amount when used within sodium guidance. Supplements should be checked for dose and chemical form. Kelp and brown seaweeds can contain very high and variable iodine, and some products may contain contaminants. Both deficiency and excess can disrupt thyroid function."],keyPoints:["Iodine supports thyroid hormone synthesis.","Iodized salt is more predictable than seaweed.","Specialty salt may not be iodized.","Too much iodine can also cause harm."],visual:{title:"Iodine safety scale",kind:"sequence",items:[{label:"No source",detail:"Deficiency risk rises when dairy, seafood and eggs are absent"},{label:"Measured source",detail:"Iodized salt or appropriately dosed supplement"},{label:"Uncertain source",detail:"Seaweed species and products vary widely"},{label:"Excess",detail:"High iodine can disrupt thyroid function"}]},mnemonic:{title:"Iodine: measured, not mysterious",cue:"Label · dose · frequency",explanation:"Replace vague 'sea vegetables' advice with a predictable plan."},goodToKnow:"Goitrogen-containing foods such as soy and crucifers are mainly concerning when iodine intake is inadequate; ordinary intake is not a reason to avoid them.",practiceConnection:"Pregnancy and thyroid disease require qualified guidance. Never confuse micrograms with milligrams—this is a thousand-fold difference.",activity:{prompt:"Which is generally the most predictable dietary iodine source?",options:[{text:"A measured amount of iodized salt",correct:true,feedback:"Correct. Its iodine addition is standardized within a jurisdiction."},{text:"Any random kelp product",correct:false,feedback:"Kelp iodine can be highly variable and excessive."},{text:"Non-iodized gourmet salt",correct:false,feedback:"It may contain little iodine."}]}} ,
      {id:"l7-m8",title:"Mineral planning is pattern plus context",highYield:"Selenium, magnesium, copper and other minerals come from overlapping foods, while soil, processing and supplements can alter exposure.",teaching:["Legumes, whole grains, nuts, seeds and vegetables provide magnesium, copper, manganese and other minerals. Selenium content is strongly influenced by soil and region; Brazil nuts can be very high and variable, so 'more is better' is unsafe. Sodium and potassium teaching also belongs in the whole pattern, not a single vegetarian label.","Minerals interact at high supplemental doses. Excess zinc can impair copper status; high-dose calcium or iron can affect absorption of other minerals in some contexts. Food-based overlap is generally safer, while diagnosed deficiency or clinical risk may warrant targeted supplementation."],keyPoints:["Plant food groups provide overlapping minerals.","Selenium content varies with soil.","High-dose minerals can interact.","Target supplementation to assessed need."],visual:{title:"Mineral planning layers",kind:"layers",items:[{label:"Pattern",detail:"Legumes, grains, nuts/seeds, vegetables and fortified foods"},{label:"Preparation",detail:"Soaking, fermentation, cooking and product formulation"},{label:"Physiology",detail:"Need, absorption, losses and adaptation"},{label:"Supplements",detail:"Dose, form, interactions and monitoring"}]},mnemonic:{title:"P-P-P-S",cue:"Pattern · Preparation · Physiology · Supplement",explanation:"A four-layer check before concluding that a mineral is low or high."},goodToKnow:"A single Brazil nut can contain a large amount of selenium, but the amount varies too much for precise dosing.",practiceConnection:"Review mineral supplements together rather than one bottle at a time; combined products can create duplicate high doses.",activity:{prompt:"Why should mineral supplements be reviewed as a group?",options:[{text:"They can duplicate doses and interact with one another",correct:true,feedback:"Correct. Total exposure matters."},{text:"Minerals never interact",correct:false,feedback:"Several minerals compete or cause adverse effects at high doses."},{text:"Food contains no minerals",correct:false,feedback:"Plant and animal foods both contain minerals."}]}} ,
      {id:"l7-m9",title:"Selenium is a soil story before it is a food list",highYield:"The selenium concentration of plant foods reflects the soil where they grew, so the same food can provide very different amounts in different regions or batches.",teaching:["Selenium is incorporated into selenoproteins that support thyroid-hormone metabolism, antioxidant defence and other enzyme systems. In plant foods, concentration is strongly shaped by soil selenium, rainfall, agricultural practices and food origin. A generic table value is therefore an estimate, not a promise about a specific bag of grains, beans or nuts.","Brazil nuts illustrate the problem: they can be exceptionally selenium-rich, but the amount per nut varies widely. Treating one or several nuts as a precision supplement can swing from modest intake to chronic excess. Repeated high exposure can produce hair and nail changes, garlic-like breath or taste, gastrointestinal symptoms and neurologic effects. Use the total pattern and a measured product when supplementation is clinically indicated."],keyPoints:["Selenium supports selenoproteins and thyroid-related enzymes.","Plant-food selenium varies with soil and origin.","Brazil nuts are too variable for exact dosing.","Both deficiency and chronic excess can be harmful."],visual:{title:"Why selenium values move",kind:"flow",items:[{label:"Soil",detail:"Regional selenium content and chemistry"},{label:"Plant uptake",detail:"Species and growing conditions"},{label:"Food batch",detail:"Origin and processing create variation"},{label:"Total intake",detail:"Foods plus every supplement"},{label:"Clinical context",detail:"Symptoms and targeted assessment when indicated"}]},mnemonic:{title:"SOIL",cue:"Source · Origin · Intake · Limit",explanation:"Selenium planning begins with origin and total exposure, not a fixed nut count."},goodToKnow:"A food-composition database gives a useful average. It cannot turn a variable natural food into a calibrated supplement.",practiceConnection:"If a client uses Brazil nuts plus a multivitamin and a thyroid product, add the selenium from all labelled supplements and ask how many nuts are eaten—then avoid making a precise dose claim from the nuts.",activity:{prompt:"Why is 'one Brazil nut equals a precise selenium dose' unreliable?",options:[{text:"Selenium content varies markedly with soil, origin and individual nut",correct:true,feedback:"Correct. Natural variation prevents precision dosing."},{text:"Brazil nuts contain no selenium",correct:false,feedback:"They can contain very large amounts."},{text:"The body cannot use selenium from food",correct:false,feedback:"Food selenium is usable; the problem is dose variability."}]}} ,
      {id:"l7-m10",title:"No single test tells the whole mineral story",highYield:"Diet records, symptoms and biomarkers answer different questions; interpret them together and avoid diagnosing deficiency from fatigue or one food log.",teaching:["A dietary assessment estimates exposure and reveals meal patterns, but it cannot prove tissue status. Symptoms such as fatigue, hair loss or poor concentration are nonspecific. Biomarkers add information but also have limits: ferritin is influenced by inflammation, serum zinc is affected by infection and fasting status, and thyroid tests can change for reasons beyond iodine intake.","Use a layered workflow: quantify foods, fortification and supplements; assess life-stage and medical risk; identify red flags; obtain appropriate laboratory data through the care team; then monitor the response to a targeted intervention. Improvement after supplementation does not prove that every person with the symptom needs that supplement. The goal is a defensible explanation, not a guess with a bottle attached."],keyPoints:["Food records estimate intake, not status.","Mineral-deficiency symptoms are often nonspecific.","Biomarkers have biological and analytic limitations.","Targeted assessment precedes high-dose treatment."],visual:{title:"Four evidence layers",kind:"layers",items:[{label:"Exposure",detail:"Foods, fortification, water and supplements"},{label:"Risk",detail:"Life stage, losses, absorption, medicines and disease"},{label:"Status",detail:"Appropriate biomarkers interpreted in context"},{label:"Response",detail:"Follow-up after a targeted, safe plan"}]},mnemonic:{title:"E-R-S-R",cue:"Exposure · Risk · Status · Response",explanation:"Four pieces of evidence protect against symptom-based supplement guessing."},goodToKnow:"A low intake estimate may justify improving the diet while a suspected clinical deficiency still needs medical assessment.",practiceConnection:"Fatigue plus a restrictive diet is a reason to assess iron, B12 and other causes—not permission to diagnose iron deficiency from fatigue alone.",activity:{prompt:"What does a three-day food record establish about iron?",options:[{text:"It estimates recent dietary exposure but does not diagnose iron deficiency",correct:true,feedback:"Correct. Status requires clinical context and appropriate biomarkers."},{text:"It proves ferritin is low",correct:false,feedback:"Ferritin is a laboratory measure and can also be influenced by inflammation."},{text:"It rules out blood loss",correct:false,feedback:"A food record cannot evaluate bleeding or other medical causes."}]}}
    ]}
  ],
  caseStudy:{title:"A vegan client using kelp and high-dose minerals",scenario:"A client avoids dairy, eggs and seafood. They use non-iodized sea salt, take kelp daily for iodine, take 50 mg zinc, and drink tea with most meals. They report fatigue and have never had laboratory assessment.",prompts:["Which iodine and zinc practices need immediate review?","How could meal timing affect iron absorption?","Which symptoms or biomarkers require medical assessment?","What safer food and supplement questions would you ask?"],takeaway:"Mineral planning requires predictable sources, dose awareness and assessment. More supplements do not automatically create better status."},
  recap:["Plant foods provide nonheme iron, whose absorption is sensitive to meal context.","Vitamin C enhances nonheme iron absorption; tea, coffee and phytate can inhibit it.","Soaking, sprouting, fermenting and leavening can reduce phytate.","Calcium content must be considered with absorption; spinach is a poor source despite its content.","Bone health includes vitamin D, protein, activity, hormones and lifestyle.","Iodized salt or a measured supplement is more predictable than kelp.","Plant-food selenium varies with soil; Brazil nuts are not precision supplements.","Diet records, symptoms and biomarkers provide different evidence and must be interpreted together.","High-dose mineral supplements can interact and should be targeted."],
  flashcards:[{front:"Nonheme iron",back:"The iron form in plant foods; its absorption is sensitive to enhancers, inhibitors and iron status.",tag:"iron"},{front:"Iron enhancer",back:"Vitamin C in the same meal can improve nonheme iron absorption.",tag:"iron"},{front:"Iron inhibitors",back:"Phytate and tea/coffee polyphenols can reduce nonheme iron absorption in the meal.",tag:"iron"},{front:"Ferritin",back:"A storage protein commonly measured when assessing iron stores, interpreted with inflammation and context.",tag:"iron"},{front:"Phytate",back:"A plant compound that can bind minerals such as zinc and iron and lower absorption.",tag:"zinc"},{front:"SSFL",back:"Soak, sprout, ferment and leaven—methods that can reduce phytate.",tag:"preparation"},{front:"Low-oxalate calcium greens",back:"Examples include kale, bok choy and broccoli.",tag:"calcium"},{front:"Spinach calcium",back:"Calcium is present, but high oxalate makes absorption poor.",tag:"calcium"},{front:"Bone-health system",back:"Calcium, vitamin D, protein, loading activity, hormones, lifestyle and clinical factors.",tag:"bone"},{front:"Predictable iodine",back:"A measured source such as iodized salt or an appropriately dosed supplement.",tag:"iodine"},{front:"Kelp risk",back:"Iodine content can be highly variable and excessive; it is not a precise dose.",tag:"iodine"},{front:"Excess zinc",back:"Can impair copper status and cause other adverse effects.",tag:"supplements"},{front:"Selenium variability",back:"Plant-food selenium reflects soil, origin and growing conditions; a table value is an estimate.",tag:"selenium"},{front:"Selenoprotein",back:"A protein containing selenium; examples support thyroid-hormone metabolism and antioxidant systems.",tag:"selenium"},{front:"E-R-S-R assessment",back:"Exposure, risk, status and response—four evidence layers for mineral assessment.",tag:"assessment"}],
  practice:[{prompt:"Name one iron-rich plant food and one vitamin-C partner.",answer:"Example: lentils with bell pepper, or tofu with broccoli.",rationale:"Vitamin C improves nonheme iron absorption.",tag:"iron"},{prompt:"Why is plant iron not a different mineral?",answer:"It is the same element, mainly in nonheme form with a different absorption pathway.",rationale:"Form and bioavailability differ, not elemental identity.",tag:"iron"},{prompt:"What beverages can reduce nonheme iron absorption in a meal?",answer:"Strong tea and coffee because of their polyphenols.",rationale:"Timing can matter when iron risk is elevated.",tag:"iron"},{prompt:"List two methods that can lower phytate.",answer:"Any two of soaking, sprouting, fermenting or leavening.",rationale:"Enzymatic or microbial action can improve mineral access.",tag:"zinc"},{prompt:"Why is spinach not a dependable calcium anchor?",answer:"Its oxalate binds calcium and makes absorption low.",rationale:"Content alone does not equal absorbed amount.",tag:"calcium"},{prompt:"Name three non-dairy calcium anchors.",answer:"Fortified plant beverage, calcium-set tofu and low-oxalate greens.",rationale:"Together they provide practical repeated coverage.",tag:"calcium"},{prompt:"Give three non-calcium factors that affect bone.",answer:"Examples: vitamin D, protein, resistance/impact activity, hormones, smoking, alcohol, medicines and age.",rationale:"Bone health is multifactorial.",tag:"bone"},{prompt:"Why is kelp not a precise iodine supplement?",answer:"Its iodine content varies widely and can be excessive.",rationale:"Predictable dosing protects against deficiency and excess.",tag:"iodine"},{prompt:"Why does microgram versus milligram matter?",answer:"A milligram is 1,000 micrograms, so a unit error can produce a thousand-fold dose error.",rationale:"The supplied pregnancy question contains this high-risk unit issue.",tag:"safety"},{prompt:"Why review all mineral supplements together?",answer:"Products may duplicate doses or create absorption and toxicity interactions.",rationale:"Total exposure matters more than one label.",tag:"supplements"},{prompt:"Why can two servings of the same plant food contain different selenium amounts?",answer:"Plant selenium depends strongly on soil concentration, geography and growing conditions.",rationale:"Natural-food values are useful averages, not calibrated doses.",tag:"selenium"},{prompt:"Why can a symptom plus a food record not diagnose mineral deficiency?",answer:"Symptoms are nonspecific and food records estimate intake rather than body status; clinical context and appropriate biomarkers are also needed.",rationale:"Different evidence layers answer different questions.",tag:"assessment"}],
  sources:[{title:"NIH ODS · Iron",url:"https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/"},{title:"NIH ODS · Zinc",url:"https://ods.od.nih.gov/factsheets/Zinc-HealthProfessional/"},{title:"NIH ODS · Calcium",url:"https://ods.od.nih.gov/factsheets/Calcium-HealthProfessional/"},{title:"NIH ODS · Iodine",url:"https://ods.od.nih.gov/factsheets/Iodine-HealthProfessional/"},{title:"NIH ODS · Selenium",url:"https://ods.od.nih.gov/factsheets/Selenium-HealthProfessional/"}]
};
